CREATE OR REPLACE FUNCTION public.privacy_change_hold(_org uuid,_case uuid,_held boolean,_actor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.complaints WHERE id=_case AND org_id=_org AND anonymised_at IS NULL AND NOT privacy_processing FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Complaint is unavailable for a hold change'; END IF; UPDATE public.complaints SET legal_hold=_held WHERE id=_case AND org_id=_org; INSERT INTO public.privacy_operations(org_id,actor,complaint_id,kind) VALUES(_org,_actor,_case,CASE WHEN _held THEN 'legal_hold_added' ELSE 'legal_hold_released' END); END $$;
REVOKE ALL ON FUNCTION public.privacy_change_hold(uuid,uuid,boolean,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.privacy_change_hold(uuid,uuid,boolean,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.privacy_retention_candidates() RETURNS TABLE(org_id uuid,retention_years integer) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT DISTINCT o.id,o.retention_years FROM public.organisations o JOIN public.complaints c ON c.org_id=o.id WHERE c.status='closed' AND NOT c.legal_hold AND c.anonymised_at IS NULL AND c.closed_at+make_interval(years=>o.retention_years)<=now() ORDER BY o.id LIMIT 5 $$;
REVOKE ALL ON FUNCTION public.privacy_retention_candidates() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.privacy_retention_candidates() TO service_role;
CREATE OR REPLACE FUNCTION public.privacy_operation_minimise() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.table_name='privacy_operations' THEN NEW.before:=NEW.before #- '{detail,reason}'; NEW.after:=NEW.after #- '{detail,reason}'; END IF; RETURN NEW; END $$;
CREATE TRIGGER privacy_operation_minimise BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION public.privacy_operation_minimise();